D[26961]={"^Increases the threat dealt by your Auto Shot ability by (.-)%%%.%s*$","Aumenta a ameaça causada por seu Tiro Automático em {{1}}%."}
D[26962]={"^Increases the critical strike chance of your Auto Shot ability by (.-)%%%.%s*$","Aumenta a chance de acerto crítico de seu Tiro Automático em {{1}}%."}
D[26963]={"^Increases the Critical Strike Damage of your Auto Shot ability by (.-)%%%.%s*$","Aumenta o dano do acerto crítico de seu Tiro Automático em {{1}}%."}
